using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketsController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;
    private readonly TicketModelService _modelService;

    public TicketsController(
        PredictionEnginePool<TicketData, TicketPrediction> predictionPool,
        TicketModelService modelService)
    {
        _predictionPool = predictionPool;
        _modelService = modelService;
    }

    [HttpPost("train")]
    public ActionResult<TrainResponse> Train()
    {
        var result = _modelService.TrainAndEvaluate();
        return Ok(result);
    }

    [HttpPost("predict")]
    public ActionResult<TicketPredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (!System.IO.File.Exists(_modelService.ModelPath))
            return BadRequest("Model has not been trained yet. Call POST /api/tickets/train first.");

        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _predictionPool.Predict(input);

        var labels = new[] { "Billing", "General", "Technical" };
        var scores = new Dictionary<string, float>();
        for (var i = 0; i < Math.Min(labels.Length, prediction.Score.Length); i++)
            scores[labels[i]] = prediction.Score[i];

        return Ok(new TicketPredictionResponse(prediction.Category, scores));
    }
}

