toolArgs.old_str:
using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketModelService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketModelService> _logger;

    public TicketModelService(IWebHostEnvironment env, ILogger<TicketModelService> logger)
    {
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        _logger = logger;
    }

    public TrainResponse TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = _mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label"))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(split.TrainSet);

        _mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);

        var perClass = new Dictionary<string, ClassMetrics>();
        for (var i = 0; i < metrics.PerClassLogLoss.Count; i++)
        {
            var cm = metrics.ConfusionMatrix;
            var precision = cm.PerClassPrecision.Count > i ? (float)cm.PerClassPrecision[i] : 0;
            var recall = cm.PerClassRecall.Count > i ? (float)cm.PerClassRecall[i] : 0;
            var f1 = precision + recall > 0 ? 2 * precision * recall / (precision + recall) : 0;
            perClass[$"Class_{i}"] = new ClassMetrics(precision, recall, f1);
        }

        return new TrainResponse(
            "Model trained and saved successfully.",
            new EvaluationMetrics(
                (float)metrics.MacroAccuracy,
                (float)metrics.MicroAccuracy,
                (float)metrics.LogLoss,
                (float)metrics.LogLossReduction,
                perClass));
    }

    public string ModelPath => _modelPath;
}

